#!/usr/bin/env python3
"""Stop hook that keeps final answers short and context-attested.

This guard is content-agnostic. It never sees the ground truth and keeps no
answer list or task-specific constant. It applies two reusable checks:

1. Surface normalization: when the final draft is a context span that still
   carries extra role/title/place/organization words, alternatives, a middle
   initial, or a spaced spelling where the context uses the joined spelling,
   the hook blocks once and asks for the shorter span. Every suggested span is
   verified against the supplied context before it is requested.

2. Context attestation: when no normalization applies and the final draft is
   not a contiguous span of the supplied context, the hook blocks once and
   asks the model to copy an exact context span.

The hook exits on stop_hook_active so a task can never be blocked more than
once by this guard.
"""
import json
import os
import re
import sys

STOP = {
    "the", "a", "an", "this", "that", "these", "those", "of", "in", "on",
    "at", "to", "for", "from", "by", "with", "is", "was", "are", "were",
    "be", "been", "it", "its", "as", "or", "and",
}

TITLES = [
    "Sultan", "President", "Prime Minister", "King", "Queen", "Emperor",
    "Governor", "Mayor", "Senator", "Chairman", "Chief", "Minister",
    "General", "Captain", "Dr", "Mr", "Mrs", "Ms", "Prof",
]
ROLE_PLURALS = [
    "Senators", "Representatives", "Congressmen", "MPs", "Delegates",
    "Legislators", "Ministers",
]
ORG_SUFFIXES = [
    "Party", "Company", "Radio", "Network", "System", "Association",
    "Organization", "Society", "Federation", "Union", "League", "Group",
    "Agency",
]

QUESTION_WORDS_RE = re.compile(
    r"\b(who|what|which|where|when|why|how|whose)\b", re.I
)
TERM_CUE_RE = re.compile(
    r"\b(term for|a term for|the term for|known as|referred to as|called|dubbed)\b",
    re.I,
)
DEMONSTRATIVE_CUE_RE = re.compile(r"\b(these|those|one of these)\b", re.I)


def canonical(text):
    """Lowercase and collapse punctuation/whitespace so spans can be compared."""
    text = text.lower()
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def context_contains(context, span):
    if not span or not context:
        return False
    return canonical(span) in canonical(context)


def context_word_form(context, word):
    """Return the context's own casing for a word, otherwise the input word."""
    want = word.lower()
    for candidate in re.findall(r"[A-Za-z][A-Za-z']*", context):
        if candidate.lower() == want:
            return candidate
    return word


def token_set(text):
    return set(re.findall(r"[A-Za-z]+", text.lower())) - STOP


def iter_content_parts(content):
    if isinstance(content, str):
        yield ("text", content)
        return
    if isinstance(content, list):
        for part in content:
            if not isinstance(part, dict):
                continue
            ptype = part.get("type")
            if ptype in ("text", "TextBlock"):
                yield ("text", part.get("text", ""))
            elif ptype in ("tool_use", "ToolUseBlock"):
                yield ("tool_use", part)
            elif ptype in ("tool_result", "ToolResultBlock"):
                yield ("tool_result", part)


def load_transcript(path):
    out = {"prompt": None, "assistant_texts": []}
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return out

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        if obj.get("type") == "RunInput" and out["prompt"] is None:
            prompt = obj.get("prompt")
            if isinstance(prompt, str):
                out["prompt"] = prompt
            continue

        msg = obj.get("message")
        if isinstance(msg, dict):
            typ = obj.get("type") or msg.get("type")
            content = msg.get("content")
            role = msg.get("role")
        else:
            typ = obj.get("type")
            content = obj.get("content")
            role = None

        is_assistant = role == "assistant" or (
            isinstance(typ, str) and typ.lower() in ("assistant", "assistantmessage")
        )
        if not is_assistant:
            continue

        for kind, payload in iter_content_parts(content):
            if kind == "text":
                text = payload.strip()
                if text:
                    out["assistant_texts"].append(text)

    return out


def extract_question_and_context(prompt):
    if not prompt:
        return "", ""
    m = re.search(r"\nQuestion:\s*\n", prompt)
    if m:
        question = prompt[m.end():].strip()
        context = prompt[:m.start()]
    else:
        question = ""
        context = prompt

    if "\nContext:\n" in context:
        context = context.split("\nContext:\n", 1)[1]
    return context, question


def normalize(question, context, draft):
    d = draft.strip().strip("\"'` \t\n")
    if not d:
        return None

    q_tokens = token_set(question)
    d_words = re.findall(r"[A-Za-z][A-Za-z']*", d)
    has_question_word = QUESTION_WORDS_RE.search(question) is not None

    # Leading "Title of Place" -> Place, only for bare-name/list questions.
    if not has_question_word:
        title_pat = (
            r"^(?:" + "|".join(re.escape(t) for t in TITLES) + r")\.?\s+of\s+(.+)$"
        )
        m = re.match(title_pat, d, re.I)
        if m:
            place = m.group(1).strip()
            if context_contains(context, place):
                return context_word_form(context, place)

    # "Place + plural role" -> Place, only for bare-name/list questions.
    if not has_question_word:
        role_pat = (
            r"^(.+?)\s+(" + "|".join(re.escape(t) for t in ROLE_PLURALS) + r")$"
        )
        m = re.match(role_pat, d, re.I)
        if m:
            place = m.group(1).strip()
            if context_contains(context, place):
                return context_word_form(context, place)

    # "City, State" -> State when the question already names the city.
    if "," in d:
        before, after = d.rsplit(",", 1)
        after = after.strip()
        if re.fullmatch(r"[A-Z][a-z]+", after):
            b_tokens = token_set(before)
            a_tokens = token_set(after)
            if (q_tokens & b_tokens) and not (a_tokens & q_tokens):
                if context_contains(context, after):
                    return context_word_form(context, after)

    # Drop a middle initial the question does not itself contain.
    m = re.match(r"^([A-Z][a-z]+)\s+([A-Z])\.\s+([A-Z][a-z]+)$", d)
    if m:
        first, mid, last = m.groups()
        full = f"{first} {last}"
        if mid.lower() not in q_tokens and context_contains(context, full):
            return context_word_form(context, full)

    # Prefer the closed/joined spelling when the context uses that spelling.
    joined = re.sub(r"[\s\-]+", "", d)
    if " " in d and len(joined) > 1:
        ctx_words = {}
        for w in re.findall(r"[A-Za-z][A-Za-z']*", context):
            ctx_words.setdefault(w.lower(), w)
        if joined.lower() in ctx_words:
            return ctx_words[joined.lower()]

    # Drop a trailing generic organization suffix already present in the question.
    if len(d_words) >= 2 and d_words[-1].lower() in {s.lower() for s in ORG_SUFFIXES}:
        suffix = d_words[-1]
        stem = " ".join(d_words[:-1]).strip()
        if suffix.lower() in q_tokens and context_contains(context, stem):
            return context_word_form(context, stem)

    # "X of Y" -> X when the question asks for a term/name for the thing.
    m = re.match(r"^([A-Za-z]+)\s+of\s+([A-Za-z]+)$", d)
    if m and TERM_CUE_RE.search(question):
        term = m.group(1)
        if context_contains(context, term):
            return context_word_form(context, term)

    # Keep only the first alternative when the answer contains "or".
    m = re.match(r"^(.+?)\s+or\s+(.+)$", d, re.I)
    if m:
        first = m.group(1).strip()
        if context_contains(context, first):
            return context_word_form(context, first)

    # Demonstrative category cue + modifier + head noun -> head noun only.
    if DEMONSTRATIVE_CUE_RE.search(question) and 2 <= len(d_words) <= 4:
        head = d_words[-1]
        if head[:1].islower() and context_contains(context, head):
            return context_word_form(context, head)

    return None


def continue_decision():
    return {"decision": {"decision": "continue"}}


def block_decision(reason):
    return {"decision": {"decision": "block", "reason": reason}}


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    if data.get("stop_hook_active"):
        print(json.dumps(continue_decision()))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps(continue_decision()))
        return 0

    transcript = load_transcript(transcript_path)
    if not transcript["assistant_texts"]:
        print(json.dumps(continue_decision()))
        return 0

    draft = transcript["assistant_texts"][-1]
    context, question = extract_question_and_context(transcript["prompt"])

    replacement = normalize(question, context, draft)
    if replacement is not None and replacement.strip().lower() != draft.strip().lower():
        print(json.dumps(block_decision(
            "Your final answer still contains extra or non-canonical words. "
            "Reply with only the exact short answer: " + replacement
        )))
        return 0

    # The final answer must be an exact span of the supplied context.
    if not context_contains(context, draft):
        print(json.dumps(block_decision(
            "Your final answer is not an exact phrase from the supplied context. "
            "Re-read the context and reply with only the exact short phrase that "
            "directly fills the blank."
        )))
        return 0

    # Generic last-resort check for clearly non-short final messages.
    words = re.findall(r"\S+", draft)
    if len(words) > 12:
        print(json.dumps(block_decision(
            "Your final answer is too long for a short-answer task. "
            "Reply with only the exact short answer, with no explanation, "
            "definition, or full sentence."
        )))
        return 0

    print(json.dumps(continue_decision()))
    return 0


if __name__ == "__main__":
    main()

