#!/usr/bin/env python3
"""Stop hook that grounds short answers in the supplied context and question.

This is intentionally conservative: it never rewrites or deletes words.  It
blocks once per stop (the runtime sets stop_hook_active on the retry) and asks
the model to resend a shorter, context-grounded answer.  The checks are all
mechanical and reusable across tasks; no task ids or expected answers are used.
"""
import json
import os
import re
import sys
import unicodedata


GENERIC_SUFFIXES = (
    "party",
    "company",
    "network",
    "system",
    "society",
    "club",
    "group",
    "movement",
    "organization",
    "organisation",
    "association",
    "league",
    "union",
)

PERSON_ROLE_WORDS = (
    r"circumnavigator|president|mayor|senator|governor|inventor|explorer|"
    r"king|queen|sultan|emperor|author|artist|actor|actress|director|"
    r"secretary|minister|leader|founder|captain|admiral|general|scientist|"
    r"composer|musician|writer|poet|painter|architect|engineer|physicist|"
    r"chemist|biologist"
)
PERSON_ROLE_RE = re.compile(r"\b(?:" + PERSON_ROLE_WORDS + r")\b", re.I)


def clean_text(value):
    """Lowercase, fold unicode, drop markup, and keep only simple word chars."""
    value = value.lower()
    value = unicodedata.normalize("NFKD", value)
    value = re.sub(r"<[^>]*>", " ", value)
    value = "".join(ch if ch.isalnum() or ch in " '&-" else " " for ch in value)
    value = re.sub(r"\s+", " ", value).strip()
    return value


def phrase_present(context_clean, phrase):
    """Return True when phrase appears in context with word boundaries."""
    if not phrase:
        return False
    pattern = re.escape(phrase)
    return re.search(r"(?<![a-z0-9])" + pattern + r"(?![a-z0-9])", context_clean) is not None


def answer_variants(text):
    """Return the cleaned answer plus the same form without a leading article."""
    cleaned = clean_text(text)
    variants = [cleaned]
    for article in ("a ", "an ", "the "):
        if cleaned.startswith(article):
            variants.append(cleaned[len(article):])
    return variants


def iter_strings(obj):
    """Yield every string nested inside a parsed JSON object."""
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, dict):
        for value in obj.values():
            yield from iter_strings(value)
    elif isinstance(obj, list):
        for value in obj:
            yield from iter_strings(value)


def read_transcript(transcript_path):
    try:
        with open(transcript_path, "r", encoding="utf-8", errors="replace") as f:
            return f.readlines()
    except Exception:
        return []


def extract_context(transcript_path):
    """Return the supplied-context text from the transcript."""
    for line in read_transcript(transcript_path):
        if "Context:" not in line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        for value in iter_strings(obj):
            if "Context:" not in value:
                continue
            idx = value.find("Context:")
            tail = value[idx + len("Context:"):]
            match = re.search(r"\n\s*Question:\s*", tail)
            if match:
                tail = tail[:match.start()]
            return tail
    return ""


def extract_question(transcript_path):
    """Return the final question line from the transcript."""
    for line in read_transcript(transcript_path):
        if "Question:" not in line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        for value in iter_strings(obj):
            if "Question:" not in value:
                continue
            idx = value.find("Question:")
            tail = value[idx + len("Question:"):].strip()
            tail = tail.splitlines()[0].strip() if tail else ""
            return tail
    return ""


def extract_final_text(transcript_path):
    """Return the final assistant/result text from a JSONL transcript."""
    texts = []
    for line in read_transcript(transcript_path):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        msg = obj.get("message") if isinstance(obj.get("message"), dict) else obj
        if isinstance(msg, dict):
            typ = obj.get("type") or msg.get("type")
            content = msg.get("content")
            role = msg.get("role")
        else:
            typ = obj.get("type")
            content = obj.get("content")
            role = None

        typ_l = (typ or "").lower()
        role_l = (role or "").lower()

        if typ_l in ("result", "resultmessage") and isinstance(obj.get("result"), str):
            texts.append(obj["result"])
            continue

        if typ_l not in ("assistant", "assistantmessage") and role_l != "assistant":
            continue

        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and isinstance(part.get("text"), str):
                    texts.append(part["text"])

    if not texts:
        return None
    return texts[-1].strip()


def is_bare_name_prompt(question):
    """Return True for prompts that are only proper names/lists with no question word."""
    question = question.strip()
    if not question or question.endswith("?"):
        return False
    tokens = [t for t in re.split(r"[,\s]+", question) if t]
    if not tokens:
        return False
    return all(tok[0].isupper() for tok in tokens)


def has_longer_name(raw_context, token):
    """Return True when a capitalized full-name phrase precedes the bare token."""
    if not raw_context or not token:
        return False
    pattern = re.compile(
        r"(?<![A-Za-z])((?:[A-Z][A-Za-z]+\.?\s+)+)" + re.escape(token) + r"(?![A-Za-z])"
    )
    return bool(pattern.search(raw_context))


def get_reason(text, context, question):
    """Return a bounded block reason, or None when the answer should pass."""
    if not text:
        return None

    words = re.findall(r"\S+", text)

    if len(words) > 12:
        return (
            "Your final answer is too long for a short-answer task. "
            "Reply with only the exact short answer from the supplied context."
        )

    if "(" in text and ")" in text:
        return (
            "Your final answer contains a parenthetical addition. Reply with "
            "only the exact short answer, with no parentheticals or extra detail."
        )
    if "\u2014" in text or " - " in text:
        return (
            "Your final answer contains an explanatory aside. Reply with only "
            "the exact short answer."
        )

    context_clean = clean_text(context)

    # Alternatives joined by 'or'/'and' are almost never a single exact answer.
    if re.search(r"\s+(?:or|and)\s+", text, re.I):
        if not any(phrase_present(context_clean, variant) for variant in answer_variants(text)):
            return (
                "Your final answer gives two alternatives. Return only the single "
                "directly cued answer from the supplied context."
            )

    # Grounding check: a multi-word answer should be an attested context phrase.
    if len(words) > 1 and context.strip():
        if not any(phrase_present(context_clean, variant) for variant in answer_variants(text)):
            return (
                "Your final answer is not a phrase from the supplied context. "
                "Reply with the exact short phrase from the context that answers "
                "the question."
            )

    # Nickname/called clues: drop a trailing category noun such as Party.
    if re.search(r"\b(nicknamed|called|dubbed)\b", question, re.I) and len(words) > 1:
        lower = text.lower()
        for suffix in GENERIC_SUFFIXES:
            if lower.endswith(" " + suffix):
                shorter = text[: -(len(suffix) + 1)].strip()
                if shorter and phrase_present(context_clean, clean_text(shorter)):
                    return (
                        "For a 'called/nicknamed/dubbed' clue, return only the "
                        "nickname/called term, not the following category word."
                    )

    # 'Term for' clues should return the short defined term, not a proper-name title.
    if re.search(r"\bterm for\b", question, re.I) and len(words) > 1 and " of " in text:
        return (
            "For a 'term for' clue, return the short defined term, not a "
            "proper-name event title."
        )

    # 'One of these' without a category noun: return the bare object noun.
    if (
        re.search(r"\bone of these\b", question, re.I)
        and len(words) >= 3
        and text == text.lower()
    ):
        head = words[-1]
        if phrase_present(context_clean, clean_text(head)):
            return (
                "Return only the bare common noun asked by the clue, not a "
                "descriptive modifier phrase."
            )

    if is_bare_name_prompt(question):
        if " of " in text:
            parts = text.split(" of ")
            if len(parts) == 2 and phrase_present(context_clean, clean_text(parts[1])):
                return (
                    "For a bare name prompt, return only the associated place, "
                    "not a title or role phrase."
                )
        if "," in text:
            parts = [p.strip() for p in text.split(",")]
            if len(parts) == 2 and phrase_present(context_clean, clean_text(parts[1])):
                return (
                    "For a bare place-name prompt, return only the shortest "
                    "associated place, not a locality-plus-place phrase."
                )
        if re.match(r"^[A-Z][^,\s]*(?:,[A-Z][^,\s]*)+$", question) and re.match(
            r"^[a-z][a-z ]+$", text, re.I
        ):
            return (
                "For a list of place names, return the specific place named in "
                "the question that the context defines, not a category."
            )

    # Person clues should not be truncated to a bare surname.
    if (
        len(words) == 1
        and re.search(r"\bthis\b", question, re.I)
        and PERSON_ROLE_RE.search(question)
    ):
        if has_longer_name(context, words[0]):
            return (
                "This clue asks about a person. Return the full name exactly as "
                "supplied in the context, including any title used before the "
                "name, not a bare surname."
            )

    return None


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    # Bound the retry: only block once per stop to avoid loops.
    if data.get("stop_hook_active"):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    text = extract_final_text(transcript_path)
    context = extract_context(transcript_path)
    question = extract_question(transcript_path)
    reason = get_reason(text, context, question)
    if reason is None:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    print(json.dumps({"decision": {"decision": "block", "reason": reason}}))
    return 0


if __name__ == "__main__":
    main()

