#!/usr/bin/env python3
"""PreToolUse hook that caps external verification at one call per tool.

This is a mechanical, content-free guard: it only counts completed WebSearch
and WebFetch calls in the current session transcript and blocks a second call.
It never inspects the question, the answer text, or any task-specific pattern.
"""

import json
import os
import sys


def allow():
    return {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "allow",
        },
        "decision": {"decision": "approve"},
    }


def deny(reason):
    return {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        },
        "decision": {"decision": "block", "reason": reason},
    }


def content_parts(content):
    """Yield (kind, payload) for a message content value."""
    if isinstance(content, str):
        yield ("text", content)
        return
    if isinstance(content, list):
        for part in content:
            if not isinstance(part, dict):
                continue
            ptype = part.get("type")
            if ptype in ("text", "TextBlock"):
                yield ("text", part.get("text", ""))
            elif ptype in ("ToolUseBlock", "tool_use"):
                yield ("tool_use", part)
            elif ptype in ("ToolResultBlock", "tool_result"):
                yield ("tool_result", part)


def count_completed_searches(transcript_path):
    """Return the number of completed WebSearch/WebFetch calls in the transcript."""
    tool_uses = {}
    completed = set()

    with open(transcript_path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue

            msg = obj.get("message")
            if isinstance(msg, dict):
                content = msg.get("content")
            else:
                content = obj.get("content")

            for kind, payload in content_parts(content):
                if kind == "tool_use":
                    uid = payload.get("id")
                    if uid:
                        tool_uses[uid] = payload.get("name")
                elif kind == "tool_result":
                    uid = payload.get("tool_use_id")
                    if uid:
                        completed.add(uid)

    count = 0
    for uid, name in tool_uses.items():
        if uid in completed and name in ("WebSearch", "WebFetch"):
            count += 1
    return count


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    tool_name = data.get("tool_name") or data.get("toolName") or ""
    if tool_name not in ("WebSearch", "WebFetch"):
        print(json.dumps(allow()))
        return 0

    # Never fight a stop that is already active; let the session finish.
    if data.get("stop_hook_active") in (True, "true", "True", 1):
        print(json.dumps(allow()))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        # If we cannot see the transcript, fail open rather than breaking the tool.
        print(json.dumps(allow()))
        return 0

    try:
        completed = count_completed_searches(transcript_path)
    except Exception:
        print(json.dumps(allow()))
        return 0

    if completed >= 1:
        print(json.dumps(deny(
            "External verification budget exhausted: at most one WebSearch "
            "and one WebFetch are allowed per task. Answer from the supplied "
            "context or from the search/fetch result you already have."
        )))
        return 0

    print(json.dumps(allow()))
    return 0


if __name__ == "__main__":
    main()

