#!/usr/bin/env python3
"""One-shot Stop hook that blocks final answers with surface forms that break short-answer exact match."""
import json
import os
import re
import sys


GENERIC_ORGANIZATION_SUFFIXES = (
    "party",
    "parties",
    "company",
    "companies",
    "network",
    "networks",
    "system",
    "systems",
    "radio",
    "association",
    "organization",
    "organisation",
    "society",
    "federation",
    "union",
    "league",
    "group",
    "groups",
    "agency",
    "agencies",
)

TERM_QUESTION_RE = re.compile(
    r"\b(term for|known as|referred to as|called|dubbed|nicknamed)\b", re.I
)

BARE_NAME_RE = re.compile(
    r"^[A-Z][A-Za-z'.\-]+(?:\s+[A-Z][A-Za-z'.\-]+){0,4}$"
)
BARE_LIST_RE = re.compile(
    r"^[A-Z][A-Za-z'.\-]+(?:,[A-Z][A-Za-z'.\-]+)+$"
)
ROLE_CATEGORY_RE = re.compile(
    r"\b(sultan|emir|king|queen|prince|princess|president|vice president|"
    r"governor|senator|senators|congressman|congresswoman|representative|"
    r"representatives|mayor|prime minister|chancellor|minister|secretary|"
    r"capital|cities|city|state|country|district|commonwealth|province|"
    r"territory|republic|kingdom|empire|dynasty|party|organization|"
    r"association)\b",
    re.I,
)
HEAD_NOUN_QUESTION_RE = re.compile(
    r"\b(?:these|those|one of these)\b", re.I
)
THIS_THESE_RE = re.compile(
    r"\b(?:this|these|that|those|one of these)\b", re.I
)
PERSON_TERM_RE = re.compile(
    r"\b(president|vice president|governor|senator|mayor|king|queen|"
    r"sultan|prince|princess|circumnavigator|explorer|inventor|author|"
    r"poet|actor|actress|singer|politician|diplomat|founder|leader|"
    r"officer|general|admiral|captain|chairman|chancellor|emperor|"
    r"assassin|murderer|criminal|killer)\b",
    re.I,
)
PERSON_PRONOUN_RE = re.compile(r"\b(?:he|she|his|her|him)\b", re.I)
MIDDLE_INITIAL_RE = re.compile(r"^([A-Z][a-z]+) [A-Z]\. ([A-Z][a-z]+)$")
HEAD_NOUN_RE = re.compile(r"^(?:\S+\s+)+[a-z][a-z]+$")
PERSON_NAME_RE = re.compile(
    r"^[A-Z][A-Za-z'.\-]+(?:\s+[A-Z][A-Za-z'.\-]+){1,3}$"
)


def _flatten(obj, out):
    if isinstance(obj, list):
        for item in obj:
            _flatten(item, out)
    elif isinstance(obj, dict):
        out.append(obj)
        for value in obj.values():
            _flatten(value, out)


def _load_objects(path):
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            raw = f.read()
    except Exception:
        return []

    objs = []
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            objs.append(json.loads(line))
        except Exception:
            pass

    if not objs:
        try:
            parsed = json.loads(raw)
        except Exception:
            parsed = None
        if isinstance(parsed, list):
            objs = parsed
        elif isinstance(parsed, dict):
            objs = [parsed]

    flat = []
    for obj in objs:
        _flatten(obj, flat)
    return flat


def extract_prompt(objs):
    for obj in objs:
        if not isinstance(obj, dict):
            continue
        prompt = obj.get("prompt")
        if isinstance(prompt, str) and prompt.strip():
            return prompt
        msg = obj.get("message")
        if isinstance(msg, dict):
            prompt = msg.get("prompt")
            if isinstance(prompt, str) and prompt.strip():
                return prompt
    return ""


def _split_prompt(prompt):
    idx = prompt.rfind("Question:")
    if idx != -1:
        return prompt[:idx], prompt[idx + len("Question:"):].strip()
    return prompt, prompt


def extract_final_text(objs):
    texts = []
    for obj in objs:
        if not isinstance(obj, dict):
            continue
        msg = obj.get("message")
        if isinstance(msg, dict):
            typ = obj.get("type") or msg.get("type") or ""
            content = msg.get("content")
            role = msg.get("role") or ""
        else:
            typ = obj.get("type") or ""
            content = obj.get("content")
            role = obj.get("role") or ""

        typ_l = typ.lower()
        role_l = role.lower()
        if typ_l not in ("assistant", "assistantmessage") and role_l != "assistant":
            continue

        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and part.get("type") in ("text", "TextBlock"):
                    texts.append(part.get("text", ""))
    if not texts:
        return ""
    return texts[-1].strip()


def _norm(s):
    s = s.strip().lower()
    s = re.sub(r"\s+", " ", s)
    s = s.strip(' .,;:!?"\'()[]')
    return s


def _in_context(span, context):
    if not span or not context:
        return False
    nspan = _norm(span)
    nctx = _norm(context)
    if nspan in nctx:
        return True
    for article in ("a ", "an ", "the "):
        if nspan.startswith(article) and nspan[len(article):] in nctx:
            return True
    return False


def _shortest_suffix_in_context(text, context):
    words = text.split()
    if len(words) < 2:
        return None
    best = None
    for i in range(1, len(words)):
        suffix = " ".join(words[i:])
        if _in_context(suffix, context):
            if best is None or len(suffix.split()) < len(best.split()):
                best = suffix
    return best


def _longest_context_name_ending_with(word, context):
    best = None
    pattern = re.compile(
        r"\b((?:[A-Z][A-Za-z'.\-]+\s+){1,4}" + re.escape(word) + r")\b"
    )
    for match in pattern.finditer(context):
        candidate = match.group(1).strip()
        if candidate.lower() == word.lower():
            continue
        if best is None or len(candidate.split()) > len(best.split()):
            best = candidate
    return best


def _strip_title_suffix(title):
    # Strip a trailing source / alternate-title suffix such as " - Site | Page"
    # or "Song / Album" before matching a quoted fragment to the title.
    return re.split(r"\s*(?:-|\||/)\s*", title, maxsplit=1)[0].strip()


def _truncated_quote_completion(question, context):
    """Return the missing title word(s) for a partial-quote question, or None."""
    frag_match = re.search(r"\.\.\.\s*\"?([^\"\n]+)\"?", question)
    if not frag_match:
        return None
    fragment = frag_match.group(1).strip().strip('"')
    if not fragment:
        return None

    completions = []
    for title_match in re.finditer(r"\[TLE\]\s*(.*?)\s*\[PAR\]", context, re.I):
        title = title_match.group(1).strip()
        stripped = _strip_title_suffix(title)
        # Case-sensitive endswith matches the quoted fragment exactly, which
        # avoids famous-phrase distractors that differ only in capitalization.
        if not stripped.endswith(fragment):
            continue
        end = context.find("[DOC]", title_match.end())
        paragraph = context[title_match.end(): end if end != -1 else len(context)]
        if not paragraph.strip().startswith(stripped):
            continue
        missing = stripped[:-len(fragment)].strip()
        if missing:
            completions.append(missing)

    if not completions:
        return None
    uniq = []
    seen = set()
    for missing in completions:
        key = missing.lower()
        if key not in seen:
            seen.add(key)
            uniq.append(missing)
    if len(uniq) == 1:
        return uniq[0]
    return None


def _emit(decision, reason=None):
    payload = {"decision": decision}
    if reason:
        payload["reason"] = reason
    print(json.dumps({"decision": payload}))


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    # Bound the retry: only block once per stop. This prevents a loop if the
    # model still returns a long answer after one revision.
    if data.get("stop_hook_active"):
        _emit("continue")
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        _emit("continue")
        return 0

    objs = _load_objects(transcript_path)
    text = extract_final_text(objs)
    if not text:
        _emit("continue")
        return 0

    prompt = extract_prompt(objs)
    context, question = _split_prompt(prompt)
    if not question:
        question = prompt

    words = re.findall(r"\S+", text)
    reason = None

    # Keep the original, highest-precision surface checks first.
    if "," in text:
        reason = (
            "Remove the comma-separated addition and reply with only the single "
            "short answer. If the comma is part of the exact answer, resend the "
            "same answer unchanged."
        )
    elif re.search(r"\bor\b", text, re.I) or "/" in text:
        reason = (
            "Your final answer contains alternatives. Keep only the single "
            "alternative cued by the most direct context sentence. If the answer "
            "itself contains that word, resend it unchanged."
        )
    elif "(" in text and ")" in text:
        reason = (
            "Remove the parenthetical addition and reply with only the short "
            "answer. If the parentheses are part of the exact answer, resend it "
            "unchanged."
        )
    elif "—" in text or " - " in text:
        reason = (
            "Remove the explanatory aside and reply with only the short answer. "
            "If the dash is part of the exact answer, resend it unchanged."
        )
    elif (
        TERM_QUESTION_RE.search(question)
        and re.search(r"\bof\b", text, re.I)
        and len(words) <= 4
    ):
        reason = (
            "Shorten this to the term itself: drop the longer title phrase and "
            "reply with only the shortest term that fills the blank. If 'of' is "
            "part of the exact term, resend it unchanged."
        )
    elif (
        TERM_QUESTION_RE.search(question)
        and text.lower().rstrip(" .").endswith(GENERIC_ORGANIZATION_SUFFIXES)
    ):
        reason = (
            "Drop the trailing generic organization/category word and reply with "
            "only the nickname or term. If that trailing word is part of the exact "
            "answer, resend it unchanged."
        )

    # Partial quotes should be completed from the context title whose exact
    # final words are the quoted fragment and whose paragraph begins with the
    # completed title. Do not let a famous phrase override that title.
    if reason is None and "..." in question:
        missing = _truncated_quote_completion(question, context)
        if missing and _norm(missing) != _norm(text):
            reason = (
                "Complete the quoted fragment with the missing title words "
                "('%s') from the supplied context title, not a famous phrase or "
                "ordinary sentence." % missing
            )

    # Bare-name/list questions should never receive an office title or broad
    # category. This is high precision because the question has no interrogative
    # and the final text contains an explicit role/category noun.
    if reason is None and (BARE_NAME_RE.match(question) or BARE_LIST_RE.match(question)):
        if ROLE_CATEGORY_RE.search(text):
            reason = (
                "This is a bare-name/list question. Return only the associated "
                "country/state/district or the specific place from the supplied "
                "context, not an office, title, or broad category."
            )

    # For these/one-of-these common-noun clues, do not send a longer descriptive
    # phrase when a shorter context span fills the same slot. Plain "this"
    # questions are excluded because many correct answers are true compound
    # nouns such as "hand dryer".
    if reason is None and HEAD_NOUN_QUESTION_RE.search(question) and not PERSON_TERM_RE.search(question):
        if HEAD_NOUN_RE.match(text):
            shorter = _shortest_suffix_in_context(text, context)
            if shorter and shorter.lower() != text.lower():
                reason = (
                    "Return only the shortest noun phrase that fills the blank. "
                    "Drop the leading descriptor(s) and use the shortest context "
                    "span (for example, '%s') if it is the direct answer." % shorter
                )

    # Person questions need full context-attested names, not bare surnames or
    # unnecessary middle initials.
    if reason is None and (PERSON_TERM_RE.search(question) or PERSON_PRONOUN_RE.search(question)):
        middle = MIDDLE_INITIAL_RE.match(text)
        if middle:
            short_name = "%s %s" % (middle.group(1), middle.group(2))
            if _in_context(short_name, context):
                reason = (
                    "Use the shorter context-attested name form without the "
                    "middle initial ('%s') unless the question itself includes "
                    "that initial." % short_name
                )
        elif len(words) == 1 and text[:1].isupper():
            full_name = _longest_context_name_ending_with(text, context)
            if full_name:
                reason = (
                    "Return the full context-attested name, not a bare surname "
                    "(for example, '%s')." % full_name
                )

    # A pronoun-only clue that does not ask "this/these" should produce a
    # person name, never a document title or described object.
    if reason is None and PERSON_PRONOUN_RE.search(question) and not THIS_THESE_RE.search(question):
        if not PERSON_NAME_RE.match(text):
            reason = (
                "Resolve the pronoun to the person named in the supplied context "
                "and return that person's fullest context-attested name. Never "
                "answer with a document title or a described object."
            )

    # Finally, enforce the context-only rule mechanically: a final answer that
    # is not a verbatim span from the supplied context is very likely a guess or
    # a title/role paraphrase rather than the requested short answer.
    if reason is None and not _in_context(text, context):
        if PERSON_PRONOUN_RE.search(question):
            reason = (
                "Resolve the pronoun to the person named in the supplied context "
                "and return that person's fullest context-attested name. Your "
                "answer is not a verbatim span from the supplied context."
            )
        else:
            reason = (
                "Your final answer must be copied verbatim from the supplied "
                "context. Choose the shortest named entity or noun phrase that "
                "appears in the context and answers the question."
            )

    if reason is None:
        _emit("continue")
        return 0

    _emit("block", reason)
    return 0


if __name__ == "__main__":
    main()

