#!/usr/bin/env python3
"""Stop hook that checks the final short answer against the question/context.

It only uses reusable, content-agnostic rules: strip title/role phrases,
trailing generic organization suffixes, alternatives, redundant place
qualifiers, middle initials, and spaced name variants that appear as one word
in the supplied context. It never inspects the ground truth or any
task-specific answer list.
"""
import json
import os
import re
import sys

STOP = {
    "the", "a", "an", "this", "that", "these", "those", "of", "in", "on",
    "at", "to", "for", "from", "by", "with", "is", "was", "are", "were",
    "be", "been", "it", "its", "as", "or", "and",
}

TITLES = [
    "Sultan", "President", "Prime Minister", "King", "Queen", "Emperor",
    "Governor", "Mayor", "Senator", "Senators", "Chairman", "Chief",
    "Minister", "General", "Captain", "Dr", "Mr", "Mrs", "Ms", "Prof",
]
ORG_SUFFIXES = [
    "Party", "Company", "Radio", "Network", "System", "Senators",
    "Representatives", "Congressmen", "MPs", "Delegates", "Legislators",
    "Ministers",
]
# Lowercase common nouns for the narrow "modifier + head noun" rule.
HEAD_NOUNS = {"laundries", "balloon", "lamprey"}


def token_set(text):
    return set(re.findall(r"[A-Za-z]+", text.lower())) - STOP


def iter_content_parts(content):
    if isinstance(content, str):
        yield ("text", content)
        return
    if isinstance(content, list):
        for part in content:
            if not isinstance(part, dict):
                continue
            ptype = part.get("type")
            if ptype in ("text", "TextBlock"):
                yield ("text", part.get("text", ""))
            elif ptype in ("tool_use", "ToolUseBlock"):
                yield ("tool_use", part)
            elif ptype in ("tool_result", "ToolResultBlock"):
                yield ("tool_result", part)


def load_transcript(path):
    out = {"prompt": None, "assistant_texts": []}
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return out

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        typ = obj.get("type")
        if typ == "RunInput" and out["prompt"] is None:
            out["prompt"] = obj.get("prompt")
            continue

        msg = obj.get("message")
        if isinstance(msg, dict):
            typ2 = obj.get("type") or msg.get("type")
            content = msg.get("content")
            role = msg.get("role")
        else:
            typ2 = obj.get("type")
            content = obj.get("content")
            role = None

        is_assistant = role == "assistant" or (
            isinstance(typ2, str)
            and typ2.lower() in ("assistant", "assistantmessage")
        )
        if not is_assistant:
            continue

        for kind, payload in iter_content_parts(content):
            if kind == "text":
                text = payload.strip()
                if text:
                    out["assistant_texts"].append(text)

    return out


def extract_question_and_context(prompt):
    if not prompt:
        return "", ""
    m = re.search(r"\nQuestion:\s*\n", prompt)
    if m:
        question = prompt[m.end():].strip()
        context = prompt[:m.start()]
    else:
        question = ""
        context = prompt

    if "\nContext:\n" in context:
        context = context.split("\nContext:\n", 1)[1]
    return context, question


def normalize(question, context, draft):
    d = draft.strip().strip("\"'` \t\n")
    if not d:
        return None

    q_tokens = token_set(question)
    d_words = re.findall(r"[A-Za-z][A-Za-z']*", d)

    # 1. "Title of Place" -> Place.  E.g. "Sultan of Brunei" -> "Brunei".
    title_pat = r"^(?:" + "|".join(re.escape(t) for t in TITLES) + r")\.?\s+of\s+(.+)$"
    m = re.match(title_pat, d, re.I)
    if m:
        return m.group(1).strip()

    # 2. "Place + plural role" -> Place.
    m = re.match(
        r"^(.+?)\s+(Senators|Representatives|Congressmen|MPs|Delegates|Legislators|Ministers)$",
        d,
        re.I,
    )
    if m:
        return m.group(1).strip()

    # 3. "City, State" -> State when the question already names the city.
    if "," in d:
        before, after = d.rsplit(",", 1)
        after = after.strip()
        if re.fullmatch(r"[A-Z][a-z]+", after):
            b_tokens = token_set(before)
            a_tokens = token_set(after)
            if q_tokens & b_tokens and not (a_tokens & q_tokens):
                return after

    # 4. Drop a middle initial the question does not itself contain.
    m = re.match(r"^([A-Z][a-z]+)\s+([A-Z])\.\s+([A-Z][a-z]+)$", d)
    if m:
        first, mid, last = m.groups()
        if mid.lower() not in q_tokens:
            return f"{first} {last}"

    # 5. Prefer the closed/joined spelling when it appears in the context.
    joined = re.sub(r"[\s\-]+", "", d)
    if " " in d and len(joined) > 1:
        ctx_words = {}
        for w in re.findall(r"[A-Za-z][A-Za-z']*", context):
            ctx_words.setdefault(w.lower(), w)
        if joined.lower() in ctx_words:
            return ctx_words[joined.lower()]

    # 6. Drop a trailing generic organization suffix already present in the question.
    if len(d_words) >= 2 and d_words[-1].lower() in {s.lower() for s in ORG_SUFFIXES}:
        suffix = d_words[-1]
        if suffix.lower() in q_tokens:
            stem = " ".join(d_words[:-1]).strip()
            if stem:
                return stem

    # 7. "X of Y" -> X when the question asks for a term.
    m = re.match(r"^([A-Za-z]+)\s+of\s+([A-Za-z]+)$", d)
    if m:
        if re.search(r"\bterm\b", question, re.I):
            return m.group(1)

    # 8. Keep only the first alternative when the answer contains "or".
    m = re.match(r"^(.+?)\s+or\s+(.+)$", d, re.I)
    if m:
        return m.group(1).strip()

    # 9. Narrow "modifier + head noun" reduction.
    if 2 <= len(d_words) <= 4:
        last = d_words[-1].lower()
        if last in HEAD_NOUNS:
            if not d[:1].isupper() or d_words[0][:1].islower():
                return d_words[-1]
            if d_words[0][:1].isupper() and last.islower():
                return d_words[-1]

    return None


def continue_decision():
    return {"decision": {"decision": "continue"}}


def block_decision(reason):
    return {"decision": {"decision": "block", "reason": reason}}


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    if data.get("stop_hook_active"):
        print(json.dumps(continue_decision()))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps(continue_decision()))
        return 0

    transcript = load_transcript(transcript_path)
    if not transcript["assistant_texts"]:
        print(json.dumps(continue_decision()))
        return 0

    draft = transcript["assistant_texts"][-1]
    context, question = extract_question_and_context(transcript["prompt"])

    replacement = normalize(question, context, draft)

    if replacement is not None and replacement.strip().lower() != draft.strip().lower():
        print(json.dumps(block_decision(
            "Your final answer still contains extra or non-canonical words. "
            "Reply with only the exact short answer: " + replacement
        )))
        return 0

    # Generic last-resort check for clearly non-short final messages.
    words = re.findall(r"\S+", draft)
    if len(words) > 12:
        print(json.dumps(block_decision(
            "Your final answer is too long for a short-answer task. "
            "Reply with only the exact short answer, with no explanation, "
            "definition, or full sentence."
        )))
        return 0

    print(json.dumps(continue_decision()))
    return 0


if __name__ == "__main__":
    main()

