#!/usr/bin/env python3
"""Stop hook that enforces the supplied-context short-answer contract once per stop."""
import json
import os
import re
import sys


def _is_text_part(part):
    return isinstance(part, dict) and part.get("type") in ("text", "TextBlock")


def _content_text(content):
    """Return the first text string found in a message content object."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        for part in content:
            if _is_text_part(part):
                text = part.get("text")
                if isinstance(text, str):
                    return text
    return ""


def extract_prompt_and_final_text(transcript_path):
    """Return (run_input_prompt, final_assistant_text) from a JSONL transcript."""
    prompt = ""
    texts = []

    try:
        with open(transcript_path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return prompt, ""

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue

        msg = obj.get("message") if isinstance(obj.get("message"), dict) else obj
        typ = obj.get("type") or msg.get("type")
        role = msg.get("role") or obj.get("role")

        if typ == "RunInput":
            candidate = obj.get("prompt") or msg.get("prompt")
            if isinstance(candidate, str) and candidate:
                prompt = candidate
            continue

        # Fallback: capture the first user/text message as the task prompt when
        # the transcript does not contain an explicit RunInput line.
        if not prompt and (typ in ("user", "UserMessage") or role == "user"):
            candidate = _content_text(msg.get("content") or obj.get("content"))
            if candidate:
                prompt = candidate
                continue

        is_assistant = typ in ("assistant", "AssistantMessage") or role == "assistant"
        if not is_assistant:
            continue

        content = msg.get("content") or obj.get("content")
        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for part in content:
                if _is_text_part(part):
                    text = part.get("text")
                    if isinstance(text, str):
                        texts.append(text)

    final = texts[-1].strip() if texts else ""
    return prompt, final


def appears_in_context(prompt, text):
    """True when the final answer (modulo a leading article and trailing punctuation)
    is a case-insensitive span of the supplied context."""
    if not prompt or not text:
        return False

    comp = text.strip().strip('"\u201c\u201d\u2018\u2019')
    comp = re.sub(r"^(a|an|the)\s+", "", comp, flags=re.IGNORECASE)
    comp = re.sub(r"[.,;:!?]+$", "", comp).strip()
    if not comp:
        return False
    return comp.lower() in prompt.lower()


def main():
    try:
        data = json.load(sys.stdin) or {}
    except Exception:
        data = {}

    # Bounded retry: block at most once per stop to avoid a revision loop.
    if data.get("stop_hook_active"):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    prompt, text = extract_prompt_and_final_text(transcript_path)
    if not text:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    words = re.findall(r"\S+", text)
    reason = None

    if not appears_in_context(prompt, text):
        reason = (
            "Your final answer does not appear as a verbatim span of the supplied "
            "context. Re-read the question and reply with only the exact short answer "
            "text that is written in the supplied context."
        )
    elif len(words) > 4:
        reason = (
            "Your final answer is too long for a short-answer task. Reply with only "
            "the exact short answer span from the supplied context, with no extra words."
        )
    elif "," in text or ";" in text or "(" in text or ")" in text:
        reason = (
            "Your final answer contains extra punctuation or a compound phrase. Reply "
            "with only the exact short answer span from the supplied context."
        )
    elif " or " in text.lower():
        reason = (
            "Your final answer contains an alternative. Choose the single exact short "
            "answer and reply with only that span from the supplied context."
        )
    elif " - " in text or "\u2014" in text:
        reason = (
            "Your final answer contains an explanatory aside. Reply with only the exact "
            "short answer span from the supplied context."
        )

    if reason is None:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    print(json.dumps({"decision": {"decision": "block", "reason": reason}}))
    return 0


if __name__ == "__main__":
    main()

