#!/usr/bin/env python3
"""Stop hook that blocks one over-elaborated or context-foreign SearchQA answer.

This is intentionally bounded: when ``stop_hook_active`` is true the hook always
continues, so the model gets at most one forced revision per stop.
"""

import json
import os
import re
import sys

GENERIC_TRAILERS = {
    "party", "parties", "company", "companies", "radio", "network",
    "networks", "system", "systems", "senator", "senators",
}

ROLE_TITLES = {
    "sultan", "king", "queen", "prince", "princess", "president",
    "prime", "governor", "senator", "mayor", "duke", "baron", "lord",
    "count", "emperor", "empress", "chancellor", "secretary", "minister",
}

HONORIFICS = {
    "sir", "lord", "lady", "king", "queen", "prince", "princess",
    "president", "governor", "senator", "mayor", "dr", "mr", "mrs", "ms",
    "professor", "captain", "admiral", "general", "colonel", "vice", "prime",
}


def content_parts(content):
    """Yield (kind, payload) for a message content value."""
    if isinstance(content, str):
        yield ("text", content)
        return
    if isinstance(content, list):
        for part in content:
            if not isinstance(part, dict):
                continue
            ptype = part.get("type")
            if ptype in ("text", "TextBlock"):
                yield ("text", part.get("text", ""))
            elif ptype in ("ToolUseBlock", "tool_use"):
                yield ("tool_use", part)
            elif ptype in ("ToolResultBlock", "tool_result"):
                yield ("tool_result", part)


def parse_transcript(path):
    """Parse a JSONL transcript into normalized message dicts."""
    messages = []
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            msg = obj.get("message")
            if isinstance(msg, dict):
                typ = obj.get("type") or msg.get("type")
                role = msg.get("role")
                content = msg.get("content")
            else:
                typ = obj.get("type")
                role = obj.get("role")
                content = obj.get("content")
            messages.append({
                "typ": typ,
                "role": role,
                "content": content,
                "raw": obj,
            })
    return messages


def first_prompt(messages):
    """Return the original task prompt, if one is visible."""
    for msg in messages:
        raw = msg.get("raw") or {}
        if isinstance(raw.get("prompt"), str) and raw["prompt"].strip():
            return raw["prompt"]
    for msg in messages:
        typ = (msg.get("typ") or "").lower()
        role = (msg.get("role") or "").lower()
        if typ not in ("user", "usermessage", "runinput") and role != "user":
            continue
        for kind, payload in content_parts(msg.get("content")):
            if kind == "text" and payload.strip():
                return payload
    return ""


def extract_question(prompt_text):
    """Return the question line from a SearchQA prompt."""
    m = re.search(
        r"Question:\s*\n?\s*(.*)$", prompt_text, re.DOTALL | re.IGNORECASE
    )
    if m:
        return m.group(1).strip()
    return prompt_text.strip()


def norm(s):
    return re.sub(r"[^a-z0-9]+", "", s.lower())


def is_bare_name_question(question):
    """Short question with no explicit interrogative."""
    if "?" in question:
        return False
    words = re.findall(r"\S+", question.strip())
    return 1 <= len(words) <= 6


def is_list_question(question):
    """Comma-separated bare list, used before stripping a trailing role word."""
    if "?" in question:
        return False
    words = re.findall(r"\S+", question.strip())
    return 1 <= len(words) <= 6 and "," in question


def is_person_name_question(question):
    """Multi-word title-case bare name, used before stripping a role 'X of Y'."""
    if "?" in question or "," in question:
        return False
    words = re.findall(r"\S+", question.strip())
    return len(words) >= 2 and all(re.match(r"^[A-Z]", w) for w in words)


def has_middle_initial(text):
    return bool(re.search(r"\b[A-Z]\.\s*[A-Z][a-zA-Z]*", text))


def result_has_content(result):
    content = result.get("content")
    if isinstance(content, str):
        return bool(content.strip())
    if isinstance(content, list):
        for item in content:
            if isinstance(item, str) and item.strip():
                return True
            if isinstance(item, dict) and item.get("text", "").strip():
                return True
    return bool(content)


def answer_grounded(text, prompt, search_texts):
    nf = norm(text)
    if not nf:
        return True
    np = norm(prompt)
    if nf in np:
        return True
    stripped = nf
    for article in ("a", "an", "the"):
        if stripped.startswith(article):
            stripped = stripped[len(article):]
            break
    if stripped and stripped in np:
        return True
    for search_text in search_texts:
        ns = norm(search_text)
        if nf in ns or (stripped and stripped in ns):
            return True
    return False


def full_name_expansion(text, prompt_text):
    """True when a single-word answer is a surname inside a longer honorific name."""
    t = text.strip().strip(".,;!?")
    if not t or len(re.findall(r"\S+", t)) != 1:
        return False
    try:
        pat = re.compile(
            r"\b((?:[A-Z][A-Za-z]+\.?[\s-]+){1,3}" + re.escape(t) + r")\b"
        )
    except Exception:
        return False
    for match in pat.finditer(prompt_text):
        phrase = match.group(1).strip()
        words = re.findall(r"[A-Za-z]+\.?", phrase)
        if 2 <= len(words) <= 4:
            first = words[0].lower().strip(".")
            if first in HONORIFICS:
                return True
    return False


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    # Bound the mechanism: never block twice for the same stop.
    if data.get("stop_hook_active") in (True, "true", "True", 1):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    try:
        messages = parse_transcript(transcript_path)
    except Exception:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    assistant_texts = []
    tool_use_names = {}
    tool_results = {}

    for msg in messages:
        typ = (msg.get("typ") or "").lower()
        role = (msg.get("role") or "").lower()
        for kind, payload in content_parts(msg.get("content")):
            if kind == "text":
                if typ in ("assistant", "assistantmessage") or role == "assistant":
                    if payload.strip():
                        assistant_texts.append(payload)
            elif kind == "tool_use":
                tool_use_names[payload.get("id")] = payload.get("name")
            elif kind == "tool_result":
                tool_results[payload.get("tool_use_id")] = payload

    if not assistant_texts:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    final_text = assistant_texts[-1].strip()
    if not final_text:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    prompt_text = first_prompt(messages)
    if not prompt_text:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    question = extract_question(prompt_text)
    question_lower = question.lower()
    words = re.findall(r"[A-Za-z0-9'.]+", final_text)
    final_lower = final_text.lower()

    search_texts = []
    for uid, result in tool_results.items():
        if (
            tool_use_names.get(uid) == "WebSearch"
            and not result.get("is_error")
            and result_has_content(result)
        ):
            content = result.get("content")
            if isinstance(content, str):
                search_texts.append(content)
            elif isinstance(content, list):
                for item in content:
                    if isinstance(item, str):
                        search_texts.append(item)
                    elif isinstance(item, dict) and item.get("text"):
                        search_texts.append(item["text"])
            elif isinstance(content, dict) and content.get("text"):
                search_texts.append(content["text"])

    reason = None

    # 1) Alternatives are never a single exact answer for a plural/definition clue.
    if reason is None and re.search(r"\bor\b", final_lower) and len(words) <= 6:
        if any(token in question_lower for token in ("these", "those", "one of these")):
            reason = (
                "Your final answer contains alternatives ('or'). Return only the "
                "single directly cued answer, with no alternatives."
            )

    # 2) A middle initial in the answer when the question does not have one.
    if reason is None and has_middle_initial(final_text) and not has_middle_initial(question):
        reason = (
            "Omit the middle initial from the name unless the question itself "
            "includes it. Return the full first and last name that directly "
            "fills the question."
        )

    # 3) Trailing role/organization word after the requested slot.
    if reason is None and words and words[0].lower() not in {"a", "an", "the"}:
        last_word = words[-1].strip(".,;!?").lower()
        if last_word in GENERIC_TRAILERS:
            cue_nickname = any(
                token in question_lower
                for token in ("nicknamed", "called", "dubbed", "known as", "term for")
            )
            question_asks_generic = last_word in question_lower or any(
                token in question_lower
                for token in ("organization", "company", "university", "party",
                              "parties", "senator", "senators", "network",
                              "system")
            )
            if cue_nickname or (is_list_question(question) and not question_asks_generic):
                reason = (
                    "Remove the trailing role/organization word "
                    f"'{words[-1].strip('.,;!?')}' and send only the shortest "
                    "exact span that fills the question."
                )

    # 4) 'X of Y' phrase where a bare term, place, or name is requested.
    if reason is None and re.match(r"^[A-Za-z]+ of [A-Za-z].*$", final_text):
        first_word = words[0].lower() if words else ""
        if (
            (first_word in ROLE_TITLES and is_person_name_question(question))
            or "term for" in question_lower
        ):
            reason = (
                "Return only the answer slot itself: the shortest term, place, "
                "or name, not a phrase containing 'of'."
            )

    # 5) Bare-name questions should not get a comma-joined location phrase.
    if reason is None and "," in final_text and "," not in question:
        if is_bare_name_question(question) and len(re.findall(r"\S+", question)) == 1:
            reason = (
                "Return only the place, state, or fact the bare term refers to, "
                "not a longer comma-joined location phrase, unless that full "
                "comma-joined phrase is itself the requested place name."
            )

    # 6) 'one of these' should get the shortest noun phrase.
    if reason is None and "one of these" in question_lower:
        if len(words) >= 3 and words[0].lower() not in {"a", "an", "the"}:
            reason = (
                "Return only the shortest noun phrase that fills 'one of these'; "
                "delete descriptive modifiers before the head noun, unless the "
                "phrase is a proper name that must stay whole."
            )

    # 7) Single-word surname should be expanded to the context's full name.
    if reason is None and full_name_expansion(final_text, prompt_text):
        if "this" in question_lower or re.search(r"\b(he|she|who)\b", question_lower):
            reason = (
                "Return the full name exactly as written in the context sentence "
                "that answers the question, including honorific and first name; do "
                "not reduce it to a bare surname."
            )

    # 8) The answer must be grounded in the supplied context or a search result.
    if reason is None and not answer_grounded(final_text, prompt_text, search_texts):
        reason = (
            "Your final answer is not an exact span from the supplied context "
            "or search result. Re-read the question and return the shortest "
            "exact span that fills the answer slot (head noun, name, or term), "
            "with no added modifiers or outside recall."
        )

    if reason is None:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    print(json.dumps({"decision": {"decision": "block", "reason": reason}}))
    return 0


if __name__ == "__main__":
    main()

