#!/usr/bin/env python3
"""Stop hook that shortens a SearchQA final answer to a context-attested span.

The hook is intentionally conservative and content-free with respect to any
specific task: it only blocks when a reusable normalization rule produces a
strictly shorter answer form and that shorter form appears verbatim in the
supplied context.  It blocks at most once per stop to avoid loops.
"""

import json
import os
import re
import sys

# Reusable lexical suffix/prefix lists.  These are not task answers; they are
# generic English role/organisation/title words that commonly pad a short
# SearchQA answer.
TRAILING_ROLE_ORGS = {
    "party", "company", "corporation", "incorporated", "inc", "ltd",
    "radio", "network", "system", "senators", "senator", "representatives",
    "representative", "congressman", "congresswoman", "president",
    "governor", "mayor", "senate", "house",
}
LEADING_TITLES = [
    "prime minister of", "president of", "governor of", "mayor of",
    "senator from", "sultan of", "king of", "queen of", "the",
]
WH_WORDS = ("who", "what", "where", "when", "why", "how", "which", "whose")


def read_transcript(path):
    """Return (prompt, last_assistant_text) parsed from a JSONL transcript."""
    prompt = None
    last_text = None
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return None, None

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        if isinstance(obj, dict):
            if obj.get("type") == "RunInput" or "prompt" in obj:
                p = obj.get("prompt")
                if isinstance(p, str) and p:
                    prompt = p

            msg = obj.get("message")
            if isinstance(msg, dict):
                typ = msg.get("type") or obj.get("type")
                content = msg.get("content")
                role = msg.get("role")
            else:
                typ = obj.get("type")
                content = obj.get("content")
                role = None

            if typ in ("assistant", "AssistantMessage") or role == "assistant":
                text = extract_text(content)
                if text is not None:
                    last_text = text
    return prompt, last_text


def extract_text(content):
    """Return the concatenated text blocks from assistant message content."""
    if isinstance(content, str):
        return content.strip()
    if not isinstance(content, list):
        return None
    parts = []
    for item in content:
        if isinstance(item, dict) and item.get("type") in ("text", "TextBlock"):
            parts.append(item.get("text", ""))
    if not parts:
        return None
    return "\n".join(parts).strip()


def split_prompt(prompt):
    """Return (context, question) from the SearchQA prompt, or (None, None)."""
    if not prompt:
        return None, None
    q_marker = "\nQuestion:\n"
    idx = prompt.rfind(q_marker)
    if idx == -1:
        m = re.search(r"\nQuestion:\s*\n", prompt)
        if not m:
            return None, None
        idx = m.start()
    question = prompt[idx + len(q_marker):].strip()
    context_start = prompt.find("Context:\n")
    if context_start == -1:
        context = prompt[:idx]
    else:
        context = prompt[context_start + len("Context:\n"):idx]
    return context, question


def context_span(text, context):
    """Return the exact context substring matching text, case-insensitively."""
    if not text or not context:
        return None
    low = text.lower()
    low_ctx = context.lower()
    pos = low_ctx.find(low)
    if pos == -1:
        return None
    return context[pos:pos + len(text)]


def in_context(text, context):
    return context_span(text, context) is not None


def canonicalize(answer, question, context):
    """Return a shorter, context-attested answer form when one is safely implied."""
    ans = answer.strip().strip("\"'").strip()
    if not ans or not context:
        return ans

    tokens = ans.split()

    # Join spaced title-case tokens if the joined form is itself in context
    # (e.g. "Show Boat" -> "Showboat" when the context uses the joined title).
    if len(tokens) >= 2 and all(t and t[0].isupper() for t in tokens):
        joined = "".join(tokens)
        span = context_span(joined, context)
        if span is not None:
            return span

    # "A or B" -> first alternative when the question asks for a single thing.
    if re.search(r"\bor\b", ans, re.I):
        first = re.split(r"\s+or\s+", ans, maxsplit=1, flags=re.I)[0].strip()
        span = context_span(first, context)
        if span is not None:
            return span

    bare_question = (
        "?" not in question
        and not re.search(r"\b(?:%s)\b" % "|".join(WH_WORDS), question, re.I)
    )

    # Bare name/list questions often append ", <state/country>"; keep the
    # state/country part when it is a shorter context-attested span.
    if "," in ans and bare_question:
        after_comma = ans.split(",")[-1].strip()
        span = context_span(after_comma, context)
        if span is not None and len(after_comma.split()) < len(tokens):
            return span

    # Remove middle initials ("Lyndon B. Johnson" -> "Lyndon Johnson") only
    # when the stripped form is itself present in context.
    stripped_initials = re.sub(r"\b[A-Z]\.\s+", "", ans).strip()
    if stripped_initials != ans and len(stripped_initials.split()) >= 2:
        span = context_span(stripped_initials, context)
        if span is not None:
            return span

    # "the term for X" clues want the head term, not the full event title.
    if re.search(r"term\s+for", question, re.I) and len(tokens) >= 2:
        head = tokens[0]
        if head.lower() not in ("a", "an", "the"):
            span = context_span(head, context)
            if span is not None:
                return span

    # Nickname/called/dubbed answers drop a trailing generic role/org word.
    nickname_clue = re.search(
        r"\b(nicknamed|called|dubbed|known\s+as)\b", question, re.I
    )
    if tokens[-1].lower() in TRAILING_ROLE_ORGS:
        shorter = " ".join(tokens[:-1])
        span = context_span(shorter, context)
        if span is not None and (nickname_clue or bare_question):
            return span

    # Bare name questions: drop a leading title phrase and keep the place or
    # entity that the context attaches to the input.
    if bare_question:
        low = ans.lower()
        for title in sorted(LEADING_TITLES, key=len, reverse=True):
            if low.startswith(title + " "):
                shorter = ans[len(title):].strip()
                span = context_span(shorter, context)
                if span is not None:
                    return span

    # "This ..." definition clues: if the model answered with a specific type,
    # keep the common-noun head when it is a lowercase context-attested word.
    if re.match(r"^this\b", question, re.I):
        if len(tokens) >= 2 and tokens[-1][0].islower():
            span = context_span(tokens[-1], context)
            if span is not None:
                return span

    # Plural/example clues ("these", "one of these"): drop leading modifiers.
    if re.search(r"\b(these|those|one of these)\b", question, re.I):
        if len(tokens) >= 3 and tokens[-1][0].islower():
            span = context_span(tokens[-1], context)
            if span is not None:
                return span

    return ans


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    # Bound the retry: after one block, let the session finish.
    if data.get("stop_hook_active"):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    try:
        prompt, final_text = read_transcript(transcript_path)
    except Exception:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    if not prompt or not final_text:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    context, question = split_prompt(prompt)
    if not context or not question:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    canonical = canonicalize(final_text, question, context)
    if not canonical or canonical.lower() == final_text.strip().lower():
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    reason = (
        "Your final answer can be shortened to the exact context span. "
        "Reply with exactly this text and nothing else: " + canonical
    )
    print(json.dumps({"decision": {"decision": "block", "reason": reason}}))
    return 0


if __name__ == "__main__":
    main()

