#!/usr/bin/env python3
"""Stop hook that blocks non-minimal or ungrounded final answers once.

This is a deterministic output guard for short-answer SearchQA runs.  It looks
at the transcript and blocks the first final assistant message that is
clearly overelaborated (punctuation lists, alternatives, middle initials,
leading title phrases, trailing generic words) or that is not copied verbatim
from the supplied context while no successful web verification was available.
"""

import json
import os
import re
import sys


def _read_transcript_lines(transcript_path, cwd):
    candidates = [transcript_path]
    if cwd:
        candidates.append(os.path.join(cwd, transcript_path))
    for path in candidates:
        if path and os.path.exists(path):
            try:
                with open(path, "r", encoding="utf-8", errors="replace") as f:
                    return f.readlines()
            except Exception:
                pass
    return []


def _content_to_text(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for part in content:
            if isinstance(part, dict):
                if part.get("type") in ("text", "TextBlock"):
                    parts.append(part.get("text", ""))
                elif part.get("type") == "thinking":
                    parts.append(part.get("thinking", ""))
                else:
                    parts.append(str(part.get("content", "")))
            else:
                parts.append(str(part))
        return "\n".join(parts)
    return ""


def _normalize(text):
    return re.sub(r"[^a-z0-9]", "", text.lower())


def _strip_leading_article(text):
    return re.sub(r"^(the|a|an)\s+", "", text.strip(), flags=re.IGNORECASE)


def extract_transcript_signal(lines):
    """Return (context_prompt, final_text, verified_search)."""
    context_prompt = None
    final_text = None
    web_tool_use_ids = set()
    web_results = {}

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue

        typ = obj.get("type")
        message = obj.get("message")

        # RunInput carries the full supplied context and question.
        if typ == "RunInput" and isinstance(obj.get("prompt"), str):
            context_prompt = obj.get("prompt")

        # New-style transcript records use AssistantMessage/UserMessage with
        # content blocks.  Also accept the older nested-message shape.
        content = None
        if isinstance(message, dict):
            content = message.get("content")
            typ = message.get("type") or typ
        else:
            content = obj.get("content")

        if not isinstance(content, (str, list)):
            continue

        if typ in ("assistant", "AssistantMessage"):
            texts = []
            if isinstance(content, str):
                texts.append(content)
            else:
                for part in content:
                    if isinstance(part, dict):
                        ptype = part.get("type")
                        if ptype == "TextBlock":
                            texts.append(part.get("text", ""))
                        elif ptype == "text":
                            texts.append(part.get("text", ""))
                        elif ptype == "ToolUseBlock" and part.get("name") in (
                            "WebSearch",
                            "WebFetch",
                        ):
                            web_tool_use_ids.add(part.get("id"))
            if texts:
                final_text = texts[-1].strip()

        elif typ in ("user", "UserMessage"):
            if isinstance(content, list):
                for part in content:
                    if isinstance(part, dict) and part.get("type") == "ToolResultBlock":
                        tool_id = part.get("tool_use_id")
                        if tool_id is not None:
                            web_results[tool_id] = (
                                part.get("is_error"),
                                _content_to_text(part.get("content", "")),
                            )

    verified_search = False
    for tool_id in web_tool_use_ids:
        result = web_results.get(tool_id)
        if result is None:
            continue
        is_error, text = result
        lowered = text.lower()
        if is_error:
            continue
        if any(marker in lowered for marker in (
            "permission",
            "denied",
            "haven't granted",
            "not permitted",
            "requires permission",
        )):
            continue
        verified_search = True
        break

    return context_prompt, final_text, verified_search


def overelaboration_reason(text, context_prompt=None):
    """Return a block reason for clearly non-minimal final answers, else None."""
    if not text:
        return None

    words = text.split()
    wc = len(words)

    # Punctuation that almost always signals a list/definition, not a
    # single short answer.
    if re.search(r"[,;()\[\]{}]", text):
        return (
            "Your final answer contains punctuation or a parenthetical addition. "
            "Reply with only the exact short answer span copied verbatim from the "
            "supplied context. If the answer itself requires that punctuation, "
            "repeat it unchanged."
        )

    if re.search(r"\bor\b", text, re.IGNORECASE):
        return (
            "Your final answer gives alternatives with 'or'. Reply with only the "
            "single exact answer span from the supplied context."
        )

    if wc > 6:
        return (
            "Your final answer is too long for a short-answer task. Reply with only "
            "the exact short answer, with no explanation or full sentence."
        )

    # Middle initial such as "Lyndon B. Johnson".  Only block when the same
    # person appears in the context with a first-name + last-name form, so we
    # do not strip initials from names that need them ("John F. Kennedy").
    middle = re.match(r"^([A-Z][a-z]+)\s+[A-Z]\.\s+([A-Z][a-z]+)$", text)
    if middle and context_prompt:
        first_last_norm = _normalize(middle.group(1) + " " + middle.group(2))
        context_norm = _normalize(context_prompt)
        if first_last_norm and first_last_norm in context_norm:
            return (
                "Your final answer includes a middle initial, but the supplied "
                "context gives the same person without it. Reply with the first name "
                "and last name only, exactly as used in the context."
            )

    # Trailing generic words that the final-answer protocol says to strip.
    suffix = (
        r"\b(Party|Company|Corporation|Network|Radio|System|Senators?|"
        r"Representatives?|Governors?|Presidents?|Mayors?|Council|Committee|"
        r"Association|League|Inc\.?|LLC|Ltd\.?)$"
    )
    if re.search(suffix, text, re.IGNORECASE):
        return (
            "Your final answer ends with a generic role, title, or organization "
            "word. Reply with only the exact short answer span from the supplied "
            "context. If that word is truly part of the exact answer, repeat the "
            "answer unchanged."
        )

    # Leading title phrases of the form "Sultan of Brunei", "President of X".
    if re.match(
        r"^(Sultan|King|Queen|President|Senator|Mayor|Governor|General|"
        r"Captain|Admiral|Prime\s+Minister|Chairman|CEO)\b",
        text,
        re.IGNORECASE,
    ) and re.search(r"\bof\b", text, re.IGNORECASE):
        return (
            "Your final answer starts with a title/role phrase. Reply with only the "
            "exact answer span from the supplied context, without the leading title. "
            "If the title is truly part of the exact answer, repeat it unchanged."
        )

    return None


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    # Bound the retry to a single revision so the hook cannot loop.
    if data.get("stop_hook_active"):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    cwd = data.get("cwd") or os.getcwd()
    lines = _read_transcript_lines(transcript_path, cwd)
    if not lines:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    context_prompt, final_text, verified_search = extract_transcript_signal(lines)
    if not context_prompt or not final_text:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    reason = overelaboration_reason(final_text, context_prompt)

    if reason is None and not verified_search:
        context_norm = _normalize(context_prompt)
        answer_norm = _normalize(final_text)
        answer_no_article_norm = _normalize(_strip_leading_article(final_text))
        if (
            answer_norm
            and answer_norm not in context_norm
            and answer_no_article_norm not in context_norm
        ):
            reason = (
                "Your final answer was not copied verbatim from the supplied "
                "context. Reply with only the exact answer span from the context. "
                "If you verified the answer with WebSearch or WebFetch, repeat it "
                "unchanged."
            )

    if reason is None:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    print(json.dumps({"decision": {"decision": "block", "reason": reason}}))
    return 0


if __name__ == "__main__":
    main()

