#!/usr/bin/env python3
"""Stop hook that blocks one obvious short-answer overelaboration.

This is intentionally bounded: it only blocks once per stop (the runtime sets
stop_hook_active on the retry), and it only fires on high-precision patterns
that are almost always wrong for the SearchQA exact-answer task.
"""
import json
import os
import re
import sys

GENERIC_SUFFIXES = {
    "party", "senator", "senators", "representative", "representatives",
    "congressman", "congresswoman", "company", "companies", "corporation",
    "corp", "inc", "network", "networks", "system", "systems", "radio",
    "channel", "station", "team", "university", "college", "airport",
    "base", "plant", "agency", "association", "alliance", "league",
    "committee", "council", "commission", "bureau", "office", "department",
    "administration", "federation", "union", "club", "group", "organization",
    "organisation",
}


def extract_final_text(transcript_path):
    """Return the final assistant text block from a JSONL transcript."""
    try:
        with open(transcript_path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return None

    texts = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        msg = obj.get("message") if isinstance(obj.get("message"), dict) else obj
        if isinstance(msg, dict):
            typ = obj.get("type") or msg.get("type")
            content = msg.get("content")
            role = msg.get("role")
        else:
            typ = obj.get("type")
            content = obj.get("content")
            role = None

        if typ != "assistant" and role != "assistant":
            continue

        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and isinstance(part.get("text"), str):
                    texts.append(part["text"])

    if not texts:
        return None
    return texts[-1].strip()


def get_reason(text):
    """Return a block reason for an obvious overelaboration, else None."""
    if not text:
        return None

    # 1. Comma-separated place/date/list instead of the bare answer.
    if "," in text:
        return (
            "Your final answer contains a comma-separated phrase. "
            "Return only the shortest answer (for a place, just the city, state, "
            "or country), not a longer place phrase or list."
        )

    # 2. Two alternatives joined by 'or' / 'and'.
    if re.search(r"^\S+\s+(?:or|and)\s+\S+$", text, re.I):
        return (
            "Your final answer gives two alternatives. Return only the single "
            "directly cued answer, not alternatives joined by 'or' or 'and'."
        )

    # 3. Middle initials in person names.
    if re.match(r"^[A-Z][a-z]+ [A-Z]\. [A-Z][a-z]+(?: [A-Z][a-z]+)?$", text):
        return (
            "Omit middle initials from person names. Return the shortest "
            "unambiguous form used in the context."
        )

    # 4. Role phrase 'Sultan of X' instead of the place X.
    if re.match(r"^Sultan of .+$", text, re.I):
        return (
            "Return only the place named after 'of', not the role phrase."
        )

    # 5. Trailing generic role/organization word after a proper-name answer.
    words = text.split()
    if len(words) > 1 and words[-1].rstrip(".").lower() in GENERIC_SUFFIXES:
        return (
            "Return only the shortest answer without the trailing role or "
            "organization word '" + words[-1] + "'."
        )

    # 6. Parenthetical or explanatory aside.
    if "(" in text and ")" in text:
        return (
            "Your final answer contains a parenthetical addition. Return only "
            "the exact short answer, with no parentheticals or extra detail."
        )
    if "—" in text or " - " in text:
        return (
            "Your final answer contains an explanatory aside. Return only the "
            "exact short answer."
        )

    return None


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    # Bound the retry: only block once per stop.
    if data.get("stop_hook_active"):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    text = extract_final_text(transcript_path)
    reason = get_reason(text)
    if reason is None:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    print(json.dumps({"decision": {"decision": "block", "reason": reason}}))
    return 0


if __name__ == "__main__":
    main()

