#!/usr/bin/env python3
"""Stop hook that shortens a SearchQA final answer to a context-attested span.

The hook is intentionally conservative and content-free with respect to any
specific task: it only blocks when a reusable normalization rule produces a
strictly better answer form and that better form appears verbatim in the
supplied context, or when the final answer is not a context span at all.  It
blocks at most once per stop to avoid loops.
"""

import json
import os
import re
import sys

# Reusable lexical suffix/prefix lists.  These are not task answers; they are
# generic English role/organisation/title words that commonly pad a short
# SearchQA answer.
TRAILING_ROLE_ORGS = {
    "party", "company", "corporation", "incorporated", "inc", "ltd",
    "radio", "network", "system", "senators", "senator", "representatives",
    "representative", "congressman", "congresswoman", "president",
    "governor", "mayor", "senate", "house",
}
LEADING_TITLES = [
    "prime minister of", "president of", "governor of", "mayor of",
    "senator from", "sultan of", "king of", "queen of",
]
WH_WORDS = ("who", "what", "where", "when", "why", "how", "which", "whose")

PERSON_QUESTION_RE = re.compile(
    r"\b(president|vice president|governor|senator|mayor|king|queen|"
    r"sultan|prince|princess|circumnavigator|explorer|inventor|author|"
    r"poet|actor|actress|singer|politician|diplomat|founder|leader|"
    r"officer|general|admiral|captain|chairman|chancellor|emperor|"
    r"assassin|murderer|criminal|killer|secretary|representative|"
    r"congressman|congresswoman)\b",
    re.I,
)
PERSON_PRONOUN_RE = re.compile(r"\b(?:he|she|his|her|him)\b", re.I)
THIS_THESE_RE = re.compile(
    r"\b(?:this|these|that|those|one of these)\b", re.I
)


def read_transcript(path):
    """Return (prompt, last_assistant_text) parsed from a JSONL transcript."""
    prompt = None
    last_text = None
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return None, None

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        if isinstance(obj, dict):
            if obj.get("type") == "RunInput" or "prompt" in obj:
                p = obj.get("prompt")
                if isinstance(p, str) and p:
                    prompt = p

            msg = obj.get("message")
            if isinstance(msg, dict):
                typ = msg.get("type") or obj.get("type")
                content = msg.get("content")
                role = msg.get("role")
            else:
                typ = obj.get("type")
                content = obj.get("content")
                role = None

            if typ in ("assistant", "AssistantMessage") or role == "assistant":
                text = extract_text(content)
                if text is not None:
                    last_text = text
    return prompt, last_text


def extract_text(content):
    """Return the concatenated text blocks from assistant message content."""
    if isinstance(content, str):
        return content.strip()
    if not isinstance(content, list):
        return None
    parts = []
    for item in content:
        if isinstance(item, dict) and item.get("type") in ("text", "TextBlock"):
            parts.append(item.get("text", ""))
    if not parts:
        return None
    return "\n".join(parts).strip()


def split_prompt(prompt):
    """Return (context, question) from the SearchQA prompt, or (None, None)."""
    if not prompt:
        return None, None
    q_marker = "\nQuestion:\n"
    idx = prompt.rfind(q_marker)
    if idx == -1:
        m = re.search(r"\nQuestion:\s*\n", prompt)
        if not m:
            return None, None
        idx = m.start()
    question = prompt[idx + len(q_marker):].strip()
    context_start = prompt.find("Context:\n")
    if context_start == -1:
        context = prompt[:idx]
    else:
        context = prompt[context_start + len("Context:\n"):idx]
    return context, question


def context_span(text, context):
    """Return the exact context substring matching text, case-insensitively."""
    if not text or not context:
        return None
    low = text.lower()
    low_ctx = context.lower()
    pos = low_ctx.find(low)
    if pos == -1:
        return None
    return context[pos:pos + len(text)]


def in_context(text, context):
    return context_span(text, context) is not None


def _norm(s):
    s = s.strip().lower()
    s = re.sub(r"\s+", " ", s)
    return s.strip(" .,;:!?\"'()[]")


def _relaxed_in_context(text, context):
    """Best-effort context match that tolerates leading articles and spacing."""
    if in_context(text, context):
        return True
    low = text.strip().lower()
    for article in ("a ", "an ", "the "):
        if low.startswith(article):
            if in_context(low[len(article):].strip(), context):
                return True
    joined = "".join(text.split())
    if joined and joined != text and in_context(joined, context):
        return True
    return False


def _strip_title_suffix(title):
    """Strip a trailing source / alternate-title suffix from a [TLE] title."""
    return re.split(r"\s*(?:-|\||/)\s*", title, maxsplit=1)[0].strip()


def _truncated_quote_completion(question, context):
    """Return the missing title word(s) for a partial-quote question, or None.

    The tie-breaker is deliberately deterministic: match the quoted fragment to
    the stripped end of a document title (case-sensitively), and prefer the
    title whose paragraph begins with the completed title.  This avoids the
    familiar-phrase default that otherwise wins when several titles match.
    """
    frag_match = re.search(r"\.\.\.\s*\"?([^\"\n]+)\"?", question)
    if not frag_match:
        return None
    fragment = frag_match.group(1).strip().strip('"')
    if not fragment:
        return None

    completions = []
    for title_match in re.finditer(
        r"\[TLE\]\s*(.*?)\s*\[PAR\]", context, re.I | re.S
    ):
        title = title_match.group(1).strip()
        stripped = _strip_title_suffix(title)
        # Case-sensitive endswith matches the quoted fragment exactly, which
        # avoids famous-phrase distractors that differ only in capitalization.
        if not stripped.endswith(fragment):
            continue
        missing = stripped[:-len(fragment)].strip()
        if not missing:
            continue
        end = context.find("[DOC]", title_match.end())
        paragraph = context[title_match.end(): end if end != -1 else len(context)]
        starts_with_completion = paragraph.strip().startswith(stripped)
        completions.append((missing, starts_with_completion))

    if not completions:
        return None

    # Prefer the completion whose paragraph begins with the completed title.
    preferred = [c for c in completions if c[1]] or completions
    unique = []
    seen = set()
    for missing, _starts in preferred:
        key = missing.lower()
        if key not in seen:
            seen.add(key)
            unique.append(missing)
    if len(unique) == 1:
        return unique[0]
    return None


def _longest_context_name_ending_with(word, context):
    """Return the longest title-case name ending with `word`, or None."""
    best = None
    pattern = re.compile(
        r"\b((?:[A-Z][A-Za-z'.\-]+\s+){1,4}" + re.escape(word) + r")\b"
    )
    for match in pattern.finditer(context):
        candidate = match.group(1).strip()
        if candidate.lower() == word.lower():
            continue
        if best is None or len(candidate.split()) > len(best.split()):
            best = candidate
    return best


