    """Return an 'in English ... called X' gloss for text, or None."""
    if not text or not context:
        return None
    low_ctx = context.lower()
    pos = 0
    while True:
        pos = low_ctx.find(text.lower(), pos)
        if pos == -1:
            return None
        window = context[pos:pos + 320]
        m = re.search(
            r"\bin English\b[^.]{0,120}?\b(?:called|known as)\s+"
            r"((?:the\s+|a\s+|an\s+)?[A-Z][^.,;|]*)",
            window,
            re.I,
        )
        if m:
            gloss = m.group(1).strip()
            if gloss and gloss.lower() != text.lower():
                return gloss
        pos += 1


