    """Return a context-attested fuller or English name form, or None."""
    tokens = text.split()

    # Bare surname for a person clue -> the longest title-case name in the
    # context that ends with that surname.
    if (
        len(tokens) == 1
        and tokens[0][:1].isupper()
        and (PERSON_QUESTION_RE.search(question) or PERSON_PRONOUN_RE.search(question))
    ):
        full = _longest_context_name_ending_with(tokens[0], context)
        if full and full.lower() != text.lower():
            return full

    # Foreign name -> the explicit English/common-name gloss when the context
    # gives one ("in English ... called the X").
    gloss = _english_gloss_for(text, context)
    if gloss and gloss.lower() != text.lower():
        return gloss

    return None


def canonicalize(answer, question, context):
    """Return a shorter, context-attested answer form when one is safely implied."""
    ans = answer.strip().strip("\"'").strip()
    if not ans or not context:
        return ans

    tokens = ans.split()

    # Join spaced title-case tokens if the joined form is itself in context
    # (e.g. "Show Boat" -> "Showboat" when the context uses the joined title).
    if len(tokens) >= 2 and all(t and t[0].isupper() for t in tokens):
        joined = "".join(tokens)
        span = context_span(joined, context)
        if span is not None:
            return span

