    # when the stripped form is itself present in context.
    stripped_initials = re.sub(r"\b[A-Z]\.\s+", "", ans).strip()
    if stripped_initials != ans and len(stripped_initials.split()) >= 2:
        span = context_span(stripped_initials, context)
        if span is not None:
            return span

    # "the term for X" clues want the head term, not the full event title.
    if re.search(r"term\s+for", question, re.I) and len(tokens) >= 2:
        head = tokens[0]
        if head.lower() not in ("a", "an", "the"):
            span = context_span(head, context)
            if span is not None:
                return span

