    """Strip a trailing source / alternate-title suffix from a [TLE] title."""
    return re.split(r"\s*(?:-|\||/)\s*", title, maxsplit=1)[0].strip()


def _truncated_quote_completion(question, context):
    """Return the missing title word(s) for a partial-quote question, or None.

    The tie-breaker is deliberately deterministic: match the quoted fragment to
    the stripped end of a document title (case-sensitively), and prefer the
    title whose paragraph begins with the completed title.  This avoids the
    familiar-phrase default that otherwise wins when several titles match.
    """
    frag_match = re.search(r"\.\.\.\s*\"?([^\"\n]+)\"?", question)
    if not frag_match:
        return None
    fragment = frag_match.group(1).strip().strip('"')
    if not fragment:
        return None

    completions = []
    for title_match in re.finditer(
        r"\[TLE\]\s*(.*?)\s*\[PAR\]", context, re.I | re.S
    ):
        title = title_match.group(1).strip()
        stripped = _strip_title_suffix(title)
        # Case-sensitive endswith matches the quoted fragment exactly, which
        # avoids famous-phrase distractors that differ only in capitalization.
        if not stripped.endswith(fragment):
            continue
        missing = stripped[:-len(fragment)].strip()
        if not missing:
            continue
        end = context.find("[DOC]", title_match.end())
        paragraph = context[title_match.end(): end if end != -1 else len(context)]
        starts_with_completion = paragraph.strip().startswith(stripped)
        completions.append((missing, starts_with_completion))

    if not completions:
        return None

    # Prefer the completion whose paragraph begins with the completed title.
    preferred = [c for c in completions if c[1]] or completions
    unique = []
    seen = set()
    for missing, _starts in preferred:
        key = missing.lower()
        if key not in seen:
            seen.add(key)
            unique.append(missing)
    if len(unique) == 1:
        return unique[0]
    return None


