    # guess, a broad category label, or a document title paraphrase.
    if not _relaxed_in_context(final_text, context):
        if PERSON_PRONOUN_RE.search(question) and not THIS_THESE_RE.search(question):
            reason = (
                "Resolve the pronoun to the person named in the supplied "
                "context and return that person's full context-attested name. "
                "Your answer is not a verbatim span from the supplied context."
            )
        else:
            reason = (
                "Your final answer must be copied verbatim from the supplied "
                "context. Choose the shortest named entity or noun phrase that "
                "appears in the context and answers the question."
            )
        _emit("block", reason)
        return 0

    _emit("continue")
    return 0


if __name__ == "__main__":
    main()

