#!/usr/bin/env python3
"""Stop hook that rejects known exact-match failure patterns once per stop."""
import json
import os
import re
import sys

US_STATES = {
    "alabama", "alaska", "arizona", "arkansas", "california", "colorado",
    "connecticut", "delaware", "florida", "georgia", "hawaii", "idaho",
    "illinois", "indiana", "iowa", "kansas", "kentucky", "louisiana",
    "maine", "maryland", "massachusetts", "michigan", "minnesota",
    "mississippi", "missouri", "montana", "nebraska", "nevada",
    "new hampshire", "new jersey", "new mexico", "new york",
    "north carolina", "north dakota", "ohio", "oklahoma", "oregon",
    "pennsylvania", "rhode island", "south carolina", "south dakota",
    "tennessee", "texas", "utah", "vermont", "virginia", "washington",
    "west virginia", "wisconsin", "wyoming",
}

CATEGORY_WORDS = {
    "capital cities", "capital city", "capitals", "cities", "countries",
    "nations", "states",
}

ROLE_SUFFIXES = [
    "senator", "senators", "party", "company", "network", "system",
    "alliance", "association", "organization", "corporation", "radio",
    "television", "channel", "hotel", "restaurant", "band", "team",
    "league", "school", "university", "college", "station", "airlines",
    "airways",
]


def norm(text):
    """Lowercase and strip punctuation so substrings can be compared."""
    text = text.lower().strip()
    text = re.sub(r"[^a-z0-9 ]", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def contains(haystack, needle):
    return norm(needle) in norm(haystack)


def get_question(prompt):
    match = re.search(r"Question:\s*\r?\n", prompt)
    if match:
        return prompt[match.end():].strip()
    lines = [line.strip() for line in prompt.strip().splitlines() if line.strip()]
    return lines[-1] if lines else ""


def parse_transcript(transcript_path):
    """Return (prompt, final_text) from a JSON-lines transcript."""
    prompt = None
    final_text = None
    result_text = None

    try:
        with open(transcript_path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return None, None

    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        obj_type = obj.get("type")

        if obj_type == "RunInput" and isinstance(obj.get("prompt"), str):
            prompt = obj["prompt"]
            continue

        # Some transcript formats nest the assistant message one level down.
        if isinstance(obj.get("message"), dict):
            msg = obj["message"]
            obj_type = obj_type or msg.get("type")
            content = msg.get("content")
            role = msg.get("role")
        elif obj_type == "ResultMessage":
            result_text = obj.get("result")
            continue
        else:
            content = obj.get("content")
            role = obj.get("role")

        is_assistant = (
            obj_type in ("AssistantMessage", "assistant")
            or role == "assistant"
        )
        if not is_assistant:
            continue

        if isinstance(content, str):
            text = content.strip()
            if text:
                final_text = text
        elif isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and part.get("type") in (
                    "text",
                    "TextBlock",
                ):
                    text = part.get("text", "").strip()
                    if text:
                        final_text = text

    if final_text is None and isinstance(result_text, str):
        final_text = result_text.strip()

    return prompt, final_text


def get_block_reason(final_text, prompt):
    if prompt is None or not final_text:
        return None

    words = re.findall(r"\S+", final_text)

    # 1. Overlong final answer.
    if len(words) > 8:
        return (
            "Your final answer is too long for a short-answer task. "
            "Reply with only the exact short answer, with no explanation, "
            "definition, or full sentence."
        )

    # 2. Parenthetical/aside punctuation (not ordinary hyphens).
    if re.search(r"[();]| — | - ", final_text):
        return (
            "Your final answer contains an explanatory aside or parenthetical. "
            "Reply with only the exact short answer and no extra punctuation."
        )

    question = get_question(prompt)

    # 3. Full place phrase where the bare state/country is the requested slot.
    if "," in final_text:
        after_comma = final_text.split(",")[-1].strip()
        qwords = question.split()
        is_location_question = (
            len(qwords) == 1 and qwords[0][:1].isupper()
        ) or question.lower().startswith("where")
        if norm(after_comma) in US_STATES and is_location_question:
            return (
                "Your final answer is a full place phrase, but the question "
                "asks only for the state. Reply with just '" + after_comma + "'."
            )

    # 4. Two alternatives where the context directly supports the first one.
    if " or " in final_text.lower():
        first_alt = final_text.split(" or ")[0].strip()
        if contains(prompt, first_alt):
            return (
                "Your final answer contains two alternatives. The supplied "
                "context directly supports '" + first_alt + "'. Reply with only "
                "that alternative."
            )

    # 5. Trailing role/qualifier word that should be stripped.
    norm_tokens = norm(final_text).split()
    original_tokens = re.findall(r"\S+", final_text)
    for idx in range(len(norm_tokens) - 1, 0, -1):
        if norm_tokens[idx] not in ROLE_SUFFIXES:
            continue
        candidate_norm = " ".join(norm_tokens[:idx])
        if contains(prompt, candidate_norm):
            candidate = " ".join(original_tokens[:idx]).strip()
            return (
                "Your final answer adds a trailing role or qualifier word. "
                "Drop it and reply with only '" + candidate + "'."
            )

    # 6. "Sultan of X" where X alone is the requested fact.
    m = re.match(r"(?i)^sultan of (.+)$", final_text.strip())
    if m and contains(prompt, m.group(1).strip()):
        return (
            "Your final answer is a role phrase. The question asks only for the "
            "associated place. Reply with just '" + m.group(1).strip() + "'."
        )

    # 7. Expanded middle-name form where the shorter two-word name is in context.
    m = re.match(r"^([A-Z][a-z]+) ([A-Z])\. ([A-Z][a-z]+)$", final_text.strip())
    if m:
        short_name = m.group(1) + " " + m.group(3)
        if contains(prompt, short_name):
            return (
                "Your final answer includes a middle initial that the context "
                "does not require. Reply with only '" + short_name + "'."
            )

    # 8. Bare list question answered with a broad category instead of the item.
    if question:
        qparts = [p.strip() for p in question.split(",")]
        if (
            len(qparts) >= 3
            and all(re.match(r"^[A-Z][a-zA-Z]+$", p) for p in qparts)
            and norm(final_text) in CATEGORY_WORDS
        ):
            return (
                "The question is a list of named items, so the answer is the "
                "specific item the context identifies for that list, not the "
                "broad category '" + final_text + "'."
            )

    # 9. Spaced title form when the compact standard spelling is in context.
    title_tokens = re.findall(r"[A-Za-z]+", final_text)
    if (
        len(title_tokens) == 2
        and title_tokens[0][:1].isupper()
        and title_tokens[1][:1].isupper()
    ):
        compact = title_tokens[0] + title_tokens[1].lower()
        if norm(compact) != norm(final_text) and contains(prompt, compact):
            return (
                "Use the standard compact title spelling. Reply with only '"
                + compact + "'."
            )

    return None


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    # Bound the retry: only block once per stop so a stubborn model cannot loop.
    if data.get("stop_hook_active"):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    prompt, final_text = parse_transcript(transcript_path)
    if prompt is None or not final_text:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    reason = get_block_reason(final_text, prompt)
    if reason is None:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    print(json.dumps({"decision": {"decision": "block", "reason": reason}}))
    return 0


if __name__ == "__main__":
    main()

