#!/usr/bin/env python3
"""Stop hook that grounds the final answer in the supplied context.

This is intentionally conservative: it never rewrites or deletes words.  It
blocks once per stop (the runtime sets stop_hook_active on the retry) and asks
the model to resend an answer that is an attested context phrase when the final
text is clearly not a short, context-grounded answer.
"""
import json
import os
import re
import sys
import unicodedata


def clean_text(value):
    """Lowercase, fold unicode, drop markup, and keep only simple word chars."""
    value = value.lower()
    value = unicodedata.normalize("NFKD", value)
    value = re.sub(r"<[^>]*>", " ", value)
    value = "".join(ch if ch.isalnum() or ch in " '&-" else " " for ch in value)
    value = re.sub(r"\s+", " ", value).strip()
    return value


def phrase_present(context_clean, phrase):
    """Return True when phrase appears in context with word boundaries."""
    if not phrase:
        return False
    pattern = re.escape(phrase)
    return re.search(r"(?<![a-z0-9])" + pattern + r"(?![a-z0-9])", context_clean) is not None


def answer_variants(text):
    """Return the cleaned answer plus the same form without a leading article."""
    cleaned = clean_text(text)
    variants = [cleaned]
    for article in ("a ", "an ", "the "):
        if cleaned.startswith(article):
            variants.append(cleaned[len(article):])
    return variants


def iter_strings(obj):
    """Yield every string nested inside a parsed JSON object."""
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, dict):
        for value in obj.values():
            yield from iter_strings(value)
    elif isinstance(obj, list):
        for value in obj:
            yield from iter_strings(value)


def extract_context(transcript_path):
    """Return the concatenated supplied-context text from the transcript."""
    try:
        with open(transcript_path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return ""

    contexts = []
    for line in lines:
        if "Context:" not in line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        found = False
        for value in iter_strings(obj):
            if "Context:" not in value:
                continue
            idx = value.find("Context:")
            tail = value[idx + len("Context:"):]
            match = re.search(r"\n\s*Question:\s*", tail)
            if match:
                tail = tail[:match.start()]
            contexts.append(tail)
            found = True
            break
        if found:
            # The first prompt/context occurrence is the supplied task context.
            break

    return "\n".join(contexts)


def extract_final_text(transcript_path):
    """Return the final assistant/result text from a JSONL transcript."""
    try:
        with open(transcript_path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return None

    texts = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue

        msg = obj.get("message") if isinstance(obj.get("message"), dict) else obj
        if isinstance(msg, dict):
            typ = obj.get("type") or msg.get("type")
            content = msg.get("content")
            role = msg.get("role")
        else:
            typ = obj.get("type")
            content = obj.get("content")
            role = None

        typ_l = (typ or "").lower()
        role_l = (role or "").lower()

        if typ_l in ("result", "resultmessage") and isinstance(obj.get("result"), str):
            texts.append(obj["result"])
            continue

        if typ_l not in ("assistant", "assistantmessage") and role_l != "assistant":
            continue

        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and isinstance(part.get("text"), str):
                    texts.append(part["text"])

    if not texts:
        return None
    return texts[-1].strip()


def get_reason(text, context):
    """Return a bounded block reason, or None when the answer should pass."""
    if not text:
        return None

    words = re.findall(r"\S+", text)

    # Clearly not a short-answer phrase.
    if len(words) > 12:
        return (
            "Your final answer is too long for a short-answer task. "
            "Reply with only the exact short answer from the supplied context."
        )

    # Parenthetical or explanatory aside.
    if "(" in text and ")" in text:
        return (
            "Your final answer contains a parenthetical addition. Reply with "
            "only the exact short answer, with no parentheticals or extra detail."
        )
    if "\u2014" in text or " - " in text:
        return (
            "Your final answer contains an explanatory aside. Reply with only "
            "the exact short answer."
        )

    # Two alternatives joined by 'or' are almost never a single exact answer.
    if re.search(r"\s+or\s+", text, re.I):
        context_clean = clean_text(context)
        if not any(phrase_present(context_clean, variant) for variant in answer_variants(text)):
            return (
                "Your final answer gives two alternatives. Return only the single "
                "directly cued answer from the supplied context."
            )

    # Grounding check: a multi-word answer should be an attested context
    # phrase. Single tokens are allowed through here to avoid blocking valid
    # acronyms or inferred one-word answers.
    if len(words) > 1 and context.strip():
        context_clean = clean_text(context)
        if not any(phrase_present(context_clean, variant) for variant in answer_variants(text)):
            return (
                "Your final answer is not a phrase from the supplied context. "
                "Reply with the exact short phrase from the context that answers "
                "the question."
            )

    return None


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = {}

    # Bound the retry: only block once per stop.
    if data.get("stop_hook_active"):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    transcript_path = data.get("transcript_path") or os.environ.get(
        "CLAUDE_TRANSCRIPT_PATH"
    )
    if not transcript_path or not os.path.exists(transcript_path):
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    text = extract_final_text(transcript_path)
    context = extract_context(transcript_path)
    reason = get_reason(text, context)
    if reason is None:
        print(json.dumps({"decision": {"decision": "continue"}}))
        return 0

    print(json.dumps({"decision": {"decision": "block", "reason": reason}}))
    return 0


if __name__ == "__main__":
    main()

